/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATORS = new Set(['+', '#', '.', '/', ';', '?', '&']);
const RESERVED_OPERATORS = new Set(['=', ',', '!', '@', '|']);

const NAME_UNIT = '(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})';
const NAME_REGEX = new RegExp(`^${NAME_UNIT}(?:\\.?${NAME_UNIT})*$`);
const MAX_LENGTH_REGEX = /^[1-9][0-9]{0,3}$/;

/**
 * Parse a single variable specification (without surrounding commas).
 *
 * @param {string} spec the raw variable specification text
 * @param {number} index index reported on error, the position of the opening `{`
 * @returns {{ name: string, explode: boolean, maxLength: (number|null) }}
 */
function parseVariableSpec(spec, index) {
  if (spec === '') throw new UriTemplateError('empty variable specification', index);

  if (spec.endsWith('*')) {
    const name = spec.slice(0, -1);
    if (!NAME_REGEX.test(name)) {
      throw new UriTemplateError(`invalid variable name '${name}'`, index);
    }
    return { name, explode: true, maxLength: null };
  }

  const colonIndex = spec.indexOf(':');
  if (colonIndex !== -1) {
    const name = spec.slice(0, colonIndex);
    const digits = spec.slice(colonIndex + 1);
    if (!NAME_REGEX.test(name)) {
      throw new UriTemplateError(`invalid variable name '${name}'`, index);
    }
    if (!MAX_LENGTH_REGEX.test(digits)) {
      throw new UriTemplateError(`invalid prefix modifier ':${digits}'`, index);
    }
    return { name, explode: false, maxLength: Number(digits) };
  }

  if (!NAME_REGEX.test(spec)) {
    throw new UriTemplateError(`invalid variable name '${spec}'`, index);
  }
  return { name: spec, explode: false, maxLength: null };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');

  const parts = [];
  let literal = '';
  let i = 0;
  const n = template.length;

  while (i < n) {
    const ch = template[i];

    if (ch === '{') {
      if (literal) {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }
      const start = i;
      const end = template.indexOf('}', start + 1);
      if (end === -1) throw new UriTemplateError('unterminated expression', start);
      const content = template.slice(start + 1, end);
      if (content === '') throw new UriTemplateError('empty expression', start);

      let operator = '';
      let rest = content;
      const first = content[0];
      if (OPERATORS.has(first)) {
        operator = first;
        rest = content.slice(1);
      } else if (RESERVED_OPERATORS.has(first)) {
        throw new UriTemplateError(`reserved operator '${first}'`, start);
      }

      const specs = rest.split(',');
      const variables = specs.map((spec) => parseVariableSpec(spec, start));
      parts.push({ type: 'expression', operator, variables });
      i = end + 1;
      continue;
    }

    if (ch === '}') {
      throw new UriTemplateError(`unexpected '}'`, i);
    }

    literal += ch;
    i += 1;
  }

  if (literal) parts.push({ type: 'literal', value: literal });
  return parts;
}
"}

